const fs   = require('fs');
const path = require('path');
const base = '/Users/jneal/n8n_projects';

const dirs = fs.readdirSync(base).filter(d => {
  try {
    const full = path.join(base, d);
    if (!fs.statSync(full).isDirectory()) return false;
    const hasVoiceover = fs.existsSync(path.join(full, 'audio', 'voiceover_final.mp3'));
    const hasTimeline  = fs.existsSync(path.join(full, 'scripts', 'media_timeline.json'));
    return hasVoiceover && !hasTimeline;
  } catch(e) { return false; }
}).sort();

if (dirs.length === 0)
  throw new Error('No Phase 2 ready projects. Need voiceover_final.mp3 but no media_timeline.json.');

const rows = dirs.map((d, i) => ({
  caseNumber: i + 1,
  slug: d,
  projectDir: path.join(base, d)
}));

return [{ json: { readyProjects: dirs, allRows: JSON.stringify(rows) } }];

const fs   = require('fs');
const path = require('path');
const selection = parseInt($json['CASE NUMBER'], 10);
const allRows   = JSON.parse($('Scan Projects').first().json.allRows);
if (!selection || selection < 1 || selection > allRows.length)
  throw new Error(`Invalid selection: ${selection}. Choose 1-${allRows.length}.`);

const row        = allRows[selection - 1];
const projectDir = row.projectDir;
const slug       = row.slug;

const voicePackage = JSON.parse(fs.readFileSync(path.join(projectDir, 'audio', 'voice_package.json'), 'utf-8'));
const topic = voicePackage.topic || slug;

return [{ json: {
  slug,
  projectDir,
  topic,
  voiceFinalPath:    path.join(projectDir, 'audio', 'voiceover_final.mp3'),
  scriptPath:        path.join(projectDir, 'scripts', 'script.md'),
  researchPath:      path.join(projectDir, 'scripts', 'research_package.json'),
  voicePackagePath:  path.join(projectDir, 'audio', 'voice_package.json'),
  mediaTimelinePath: path.join(projectDir, 'scripts', 'media_timeline.json'),
  imageManifestPath: path.join(projectDir, 'scripts', 'image_manifest.json'),
  videoManifestPath: path.join(projectDir, 'scripts', 'video_manifest.json'),
  metadataPath:      path.join(projectDir, 'scripts', 'metadata_package.json')
} }];

const fs   = require('fs');
const dur  = parseFloat(($input.item.json.stdout || '').trim()) || 0;
const mm   = Math.floor(dur / 60);
const ss   = Math.round(dur % 60);
const vars = $('Load Project').first().json;

const scriptText   = fs.readFileSync(vars.scriptPath, 'utf-8');
const voicePackage = JSON.parse(fs.readFileSync(vars.voicePackagePath, 'utf-8'));
const wordCount    = scriptText.split(/\s+/).filter(w => w.length > 0).length;
const wpm          = dur > 0 ? Math.round((wordCount / dur) * 60) : 150;

return [{ json: {
  ...vars,
  durationSeconds: Math.round(dur * 10) / 10,
  durationMMSS:    `${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`,
  wordCount,
  wpm,
  scriptText,
  voicePackage
} }];

