const fs   = require('fs');
const inp  = $input.first().json;
const vars = $('Build Media Placement Prompt').first().json;
if (inp.exitCode !== undefined && inp.exitCode !== 0)
  throw new Error('Media Placement Agent error: ' + inp.error);

let raw = (inp.output || '').trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();

let timeline;
try { timeline = JSON.parse(raw); }
catch(e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Cannot parse media_timeline.json. Raw: ' + raw.substring(0,300));
  timeline = JSON.parse(raw.substring(s, en + 1));
}

fs.writeFileSync(vars.mediaTimelinePath, JSON.stringify(timeline, null, 2), 'utf-8');
console.log(`media_timeline.json saved: ${(timeline.scenes||[]).length} scenes, ${(timeline.music_cues||[]).length} music cues, ${(timeline.sfx_cues||[]).length} sfx cues`);
return [{ json: { ...vars, timeline } }];

