const item = $input.item.json;
const p    = item.rawPrompt.prompt || {};

// Build positive prompt from NB2 JSON fields
const positiveFields = ['goal','context','style','composition','lighting','mood','background'];
const positiveText = [
  p.goal || '',
  Array.isArray(p.subject) ? p.subject.join(', ') : (p.subject || ''),
  p.context || '',
  p.style || 'photorealistic, hyper-detailed, cinematic',
  p.composition || '',
  p.lighting || '',
  Array.isArray(p.color_palette) ? p.color_palette.join(', ') : '',
  p.background || '',
  (() => { const c = p.camera_or_lens || {}; return [c.focal_length, c.type, c.aperture].filter(Boolean).join(' '); })(),
  p.mood || ''
].filter(Boolean).join(', ');

const negText = Array.isArray(p.negative_constraints)
  ? p.negative_constraints.join(', ')
  : 'modern elements, anachronistic objects, artificial studio lighting, oversaturated colors, watermark';

const kieInput = { prompt: positiveText, width: 1920, height: 1080, num_images: 1 };
if (negText) kieInput.negative_prompt = negText;

return [{ json: {
  ...item,
  kieBody:    JSON.stringify({ model: 'nano-banana-2', input: kieInput }),
  promptText: positiveText
} }];

