const data = poll.data || {};
if (data.errorCode)
  throw new Error(`${meta.filename} failed: ${data.errorCode} — ${data.errorMessage}`);

let resp = data.response || {};
if (typeof resp === 'string') { try { resp = JSON.parse(resp); } catch(e) {} }
const assetUrl = (resp.resultUrls||[])[0] || resp.videoUrl || resp.url || resp.video_url || '';
