sd.videoCost  = (sd.videoCost  || 0) + (data.creditsConsumed || 0);
sd.videoCount = (sd.videoCount || 0) + 1;

return [{ json: {
  ...meta,
  assetUrl,
  filepath: meta.assetDir + '/' + meta.filename + '.mp4',
  creditsConsumed: data.creditsConsumed || 0
} }];

